from __future__ import annotations
import datetime
import ipaddress
import json
import logging
import os
import threading
import time

from flask import request
from flask_restful import Resource

from hiddifypanel.panel import hiddify
from hiddifypanel.models import User, Domain, ConfigEnum, UserMode, AdminUser, hconfig
from hiddifypanel.database import db
from hiddifypanel.hutils.tg_texts import trial_settings

logger = logging.getLogger(__name__)

ONE_GIG = 1024 ** 3
# the trial limits are the bot's trial setting (hutils/tg_texts.trial_settings: GB / days / devices, editable on the Telegram page of the panel)

_CORS_ORIGIN = 'https://@@SUPPORT_DOMAIN@@'

# ----------------------------------------------------------------------------------------------------------------------------- abuse limits
# Everything below is counted per client address, in Redis (shared by every process, survives a restart of the panel). Without Redis the memory of this process is used.
#   ip_window_max requests in ip_window_s seconds   - any request counts, also a bad one: nobody can hammer the endpoint
#   ip_hour_max requests per hour
#   ip_day_created_max trial accounts created per day from one address
#   global_hour_created_max trial accounts created per hour by everybody together: a circuit breaker (one message to the admin), a flood from many addresses stops here
# The numbers can be changed without a restart in LIMITS_FILE ({"ip_window_s": 120, ...}); a missing / broken / out-of-range value means the default.
LIMITS_FILE = os.environ.get('HIDDIFY_TRIAL_LIMITS_FILE', '/opt/hiddify-manager/hiddify-panel/var/trial-limits.json')
DEFAULT_LIMITS = {'ip_window_s': 120, 'ip_window_max': 3, 'ip_hour_max': 10, 'ip_day_created_max': 3, 'global_hour_created_max': 12}
_MAX_BODY = 2048
_PHONE_LOCK_S = 30

_limits_cache: dict = {'mtime': None, 'value': dict(DEFAULT_LIMITS)}
_mem: dict = {}
_mem_lock = threading.Lock()


def _limits() -> dict:
    try:
        mtime = os.stat(LIMITS_FILE).st_mtime
    except OSError:
        return dict(DEFAULT_LIMITS)
    if _limits_cache['mtime'] == mtime:
        return _limits_cache['value']
    value = dict(DEFAULT_LIMITS)
    try:
        with open(LIMITS_FILE, encoding='utf-8') as f:
            data = json.load(f)
        for k in DEFAULT_LIMITS:
            v = data.get(k) if isinstance(data, dict) else None
            if isinstance(v, int) and not isinstance(v, bool) and 1 <= v <= 100000:
                value[k] = v
    except (OSError, ValueError):
        pass
    _limits_cache.update(mtime=mtime, value=value)
    return value


def _redis():
    try:
        from hiddifypanel.cache import redis_client
        return redis_client if hasattr(redis_client, 'incr') else None
    except Exception:
        return None


def _mem_purge(now: float) -> None:
    if len(_mem) > 5000:
        for k in [k for k, (exp, _n) in _mem.items() if exp <= now]:
            _mem.pop(k, None)


def _incr(key: str, ttl: int) -> int:
    """add one to a counter that lives `ttl` seconds from its first hit; returns the new value"""
    r = _redis()
    if r is not None:
        try:
            n = int(r.incr(key))
            if n == 1 or int(r.ttl(key)) < 0:          # no expiry yet (first hit, or a crash between incr and expire): set it
                r.expire(key, ttl)
            return n
        except Exception as exc:
            logger.warning('web trial: redis counter failed (%s), using the memory of this process', exc)
    now = time.time()
    with _mem_lock:
        exp, n = _mem.get(key, (0.0, 0))
        if exp <= now:
            exp, n = now + ttl, 0
        n += 1
        _mem[key] = (exp, n)
        _mem_purge(now)
        return n


def _peek(key: str) -> int:
    r = _redis()
    if r is not None:
        try:
            v = r.get(key)
            return int(v) if v is not None else 0
        except Exception:
            pass
    with _mem_lock:
        exp, n = _mem.get(key, (0.0, 0))
        return n if exp > time.time() else 0


def _ttl(key: str, default: int) -> int:
    r = _redis()
    if r is not None:
        try:
            t = int(r.ttl(key))
            return t if t > 0 else default
        except Exception:
            pass
    with _mem_lock:
        exp, _n = _mem.get(key, (0.0, 0))
        return max(1, int(exp - time.time())) if exp > time.time() else default


def _once(key: str, ttl: int) -> bool:
    """True for the first caller within `ttl` seconds (a lock / a "tell the admin only once" mark)"""
    r = _redis()
    if r is not None:
        try:
            return bool(r.set(key, '1', nx=True, ex=ttl))
        except Exception:
            pass
    now = time.time()
    with _mem_lock:
        exp, _n = _mem.get(key, (0.0, 0))
        if exp > now:
            return False
        _mem[key] = (now + ttl, 1)
        return True


def _release(key: str) -> None:
    r = _redis()
    if r is not None:
        try:
            r.delete(key)
        except Exception:
            pass
    with _mem_lock:
        _mem.pop(key, None)


def _cors():
    return {
        'Access-Control-Allow-Origin': _CORS_ORIGIN,
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
    }


def _normalize_phone(value):
    raw = (value or '').strip() if isinstance(value, str) else ''
    digits = ''.join(ch for ch in raw if ch.isdigit())
    if not digits:
        return ''
    if digits.startswith('8') and len(digits) == 11:
        digits = '7' + digits[1:]
    if not digits.startswith('7') and len(digits) == 10:
        digits = '7' + digits
    if not digits.startswith('7') or len(digits) != 11:
        return ''
    return f'+{digits}'


def _find_user(phone: str):
    return User.query.filter(
        (User.name == phone) | (User.username == phone)
    ).order_by(User.id.desc()).first()


def _default_added_by():
    admin = AdminUser.query.order_by(AdminUser.id.asc()).first()
    return admin.id if admin else 1


def _sub_url(user: User) -> str:
    domain = Domain.get_domains()[0]
    proxy_path = hconfig(ConfigEnum.proxy_path_client)
    return f'https://{domain.domain}/{proxy_path}/{user.uuid}/'


def _create_trial_user(phone: str) -> User:
    trial = trial_settings()
    user = User(
        name=phone,
        username=phone,
        telegram_id=None,
        added_by=_default_added_by(),
        enable=True,
        usage_limit=int(trial['gb'] * ONE_GIG),
        package_days=trial['days'],
        max_ips=trial['max_ips'],
        mode=UserMode.no_reset,
        start_date=datetime.date.today(),
        last_reset_time=datetime.date.today(),
        comment='Web trial signup',
    )
    db.session.add(user)
    db.session.commit()
    db.session.refresh(user)
    hiddify.quick_apply_users()
    return user


def _client_ip() -> str:
    """The client's address. nginx writes it into X-Real-IP (it takes it from the PROXY protocol of haproxy, a client cannot set it) and the panel listens on
    127.0.0.1 only, so the header is nginx's. X-Forwarded-For is typed by the client and is NOT used. An IPv6 client counts as its whole /64 (it owns billions of addresses)."""
    # the panel wraps the app in ProxyFix, which turns request.remote_addr into the last X-Forwarded-For entry: the real peer of the connection is kept in the environ
    peer = (request.environ.get('werkzeug.proxy_fix.orig') or {}).get('REMOTE_ADDR') or request.environ.get('REMOTE_ADDR') or ''
    for cand in (request.headers.get('X-Real-IP', ''), peer):
        try:
            ip = ipaddress.ip_address(cand.strip().strip('[]'))
        except ValueError:
            continue
        if ip.version == 6:
            return str(ipaddress.ip_network(f'{ip}/64', strict=False).network_address) + '/64'
        return str(ip)
    return 'unknown'


def _tell_admin(text: str) -> None:
    """one Telegram message to the admins that have a Telegram account; in a thread, the answer to the visitor does not wait for Telegram"""
    from flask import current_app
    app_obj = current_app._get_current_object()

    def run():
        try:
            with app_obj.app_context():
                from hiddifypanel.panel.commercial.telegrambot import bot
                from hiddifypanel.panel.commercial.telegrambot.secrets import telegram_bot_token
                token = telegram_bot_token()
                if not bot or not token:
                    return
                bot.token = token
                for admin in AdminUser.query.filter(AdminUser.telegram_id.isnot(None)).all():
                    bot.send_message(int(admin.telegram_id), text)
        except Exception as exc:  # noqa: BLE001
            logger.warning('web trial: could not tell the admin (%s)', type(exc).__name__)

    threading.Thread(target=run, daemon=True).start()


def _error(message: str, code: int, headers: dict, retry_after: int | None = None):
    h = dict(headers)
    if retry_after:
        h['Retry-After'] = str(int(retry_after))
    return {'status': 'error', 'message': message}, code, h


class WebTrialResource(Resource):
    def options(self, **_):
        return {}, 200, _cors()

    def post(self, **_):
        headers = _cors()
        try:
            lim = _limits()
            ip = _client_ip()

            # 1. how often this address may knock at all (a bad request counts too)
            wkey = f'trial:w:{ip}'
            if _incr(wkey, lim['ip_window_s']) > lim['ip_window_max']:
                wait = _ttl(wkey, lim['ip_window_s'])
                return _error(f'Слишком много запросов. Попробуйте через {max(1, (wait + 59) // 60)} мин.', 429, headers, wait)
            hkey = f'trial:h:{ip}'
            if _incr(hkey, 3600) > lim['ip_hour_max']:
                wait = _ttl(hkey, 3600)
                return _error('Слишком много запросов. Попробуйте позже.', 429, headers, wait)

            if request.content_length and request.content_length > _MAX_BODY:
                return _error('Запрос слишком большой.', 413, headers)
            data = request.get_json(silent=True)
            data = data if isinstance(data, dict) else {}
            phone = _normalize_phone(data.get('phone', ''))
            if not phone:
                return _error('Введите корректный номер в формате +7XXXXXXXXXX', 400, headers)

            # 2. two requests for one number at the same moment must not make two accounts
            lock_key = f'trial:p:{phone}'
            if not _once(lock_key, _PHONE_LOCK_S):
                return _error('Запрос по этому номеру уже обрабатывается. Подождите полминуты.', 429, headers, _PHONE_LOCK_S)

            try:
                existing = _find_user(phone)
                if existing:
                    return {
                        'status': 'exists',
                        'message': 'Пробная подписка на этот номер уже выдавалась',
                    }, 200, headers

                # 3. how many accounts this address may create per day, and the circuit breaker for the whole service
                dkey = f'trial:cd:{ip}'
                if _peek(dkey) >= lim['ip_day_created_max']:
                    return _error('С этого адреса на сегодня выдано максимум пробных подписок. Попробуйте завтра.', 429, headers, _ttl(dkey, 86400))
                gkey = 'trial:cg'
                if _peek(gkey) >= lim['global_hour_created_max']:
                    if _once('trial:alert', 3600):
                        _tell_admin(f"Веб-триал: за последний час выдано {lim['global_hour_created_max']} пробных подписок, новые временно не выдаются "
                                    f"(предохранитель). Если это не наплыв людей, возможно, кто-то накручивает регистрации. "
                                    f"Лимит меняется в {LIMITS_FILE} (global_hour_created_max).")
                    return _error('Сейчас много заявок. Попробуйте через час.', 503, headers, _ttl(gkey, 3600))

                user = _create_trial_user(phone)
                _incr(dkey, 86400)
                _incr(gkey, 3600)
                trial = trial_settings()
                return {
                    'status': 'created',
                    'sub_url': _sub_url(user),
                    'message': (
                        f"Пробная подписка создана на {trial['days']} дн., "
                        f"лимит {trial['gb_text']} ГБ, устройств: {trial['max_ips']}"
                    ),
                }, 201, headers
            finally:
                _release(lock_key)          # held only while this request is handled, a refused request must not block the number

        except Exception as exc:
            db.session.rollback()
            logger.exception('Web trial signup failed: %s', exc)
            return {
                'status': 'error',
                'message': 'Внутренняя ошибка. Попробуйте позже.',
            }, 500, headers
